import requests, xml.etree.ElementTree as ET
pmid='25075066'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':pmid,'rettype':'abstract','retmode':'xml'},timeout=20)
root=ET.fromstring(r.text)
for tag in ['ArticleTitle','AbstractText','ArticleId']:
    for e in root.iter(tag):
        print(tag, e.attrib, ''.join(e.itertext()).strip())
print('JOURNAL/AUTHORS')
for e in root.findall('.//Author')[:8]: print(''.join(e.itertext()).strip())
for e in root.findall('.//JournalIssue/PubDate'): print(''.join(e.itertext()).strip())
print('PMCID', [e.text for e in root.findall('.//ArticleId') if e.attrib.get('IdType')=='pmc'])
